    _get_ptx_module().function("conv_transpose2d_nchw_kernel")

def _pair(v):
    return v if isinstance(v, tuple) else (v, v)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = _pair(kernel_size)
        self.stride = _pair(stride)
        self.padding = _pair(padding)
        self.dilation = _pair(dilation)
        self.groups = groups
        self.in_per_group = in_channels // groups
        self.out_per_group = out_channels // groups

        holder = nn.Module()
        holder.weight = nn.Parameter(torch.empty(in_channels, self.out_per_group, self.kernel_size[0], self.kernel_size[1]))
        if bias:
            holder.bias = nn.Parameter(torch.empty(out_channels))
        else:
            holder.register_parameter("bias", None)
        self.conv_transpose2d = holder

        with torch.no_grad():
            nn.init.kaiming_uniform_(self.conv_transpose2d.weight, a=math.sqrt(5))
            if self.conv_transpose2d.bias is not None:
                fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
                bound = 1.0 / math.sqrt(fan_in)
                self.conv_transpose2d.bias.uniform_(-bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        b, ic, h, w = x.shape
        kh, kw = self.kernel_size
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation
        oh = (h - 1) * sh - 2 * ph + dh * (kh - 1) + 1
        ow = (w - 1) * sw - 2 * pw + dw * (kw - 1) + 1
        out = torch.empty((b, self.out_channels, oh, ow), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        weight = self.conv_transpose2d.weight
        bias = self.conv_transpose2d.bias
        has_bias = 1 if bias is not None else 0
        bias_arg = bias if bias is not None else out
        total = b * self.out_channels * oh * ow
        ow_tile = max(1, 256 // self.out_per_group)
        block_x = self.out_per_group * ow_tile
        num_ow_tiles = (ow + ow_tile - 1) // ow_tile
        grid_x = b * self.groups * oh * num_ow_tiles
