                weight,
                out,
                bias_arg,
                i32(has_bias),
                i32(total),
                i32(b),
                i32(ic),
                i32(h),
                i32(w),
                i32(self.out_channels),
                i32(oh),
                i32(ow),
                i32(kh),
                i32(kw),
                i32(sh),
                i32(sw),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
                i32(self.groups),
                i32(self.in_per_group),
